// Headers for every route that returns stored or generated BYTES (an image, an export): not the SPA shell, not JSON.
//
// Why: /api/images/:id sends the stored content type. An SVG opened as a page (top-level navigation, a new tab) runs its
// <script> on the app origin with the user's session. These headers close that for every byte route:
//   - Content-Security-Policy: sandbox + default-src 'none' makes the document inert even if it is rendered;
//   - X-Content-Type-Options: nosniff keeps the declared type;
//   - Content-Disposition: attachment for everything but a raster image the app loads as <img> (an <img> never runs
//     SVG script, so inline is safe for it; the header protects the top-level navigation).
// A small per-route helper, not a global middleware: the SPA shell must keep its own policy (server/securityHeaders.ts).
// MCP View frames (server/mcpApps.ts buildViewCsp) have their own policy and do not use this.

export const ARTIFACT_CSP = "default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'; sandbox"

/** The image types a browser decodes as pixels only. SVG is deliberately NOT here: it is a document that can carry script. */
const RASTER = new Set(['image/png', 'image/jpeg', 'image/jpg', 'image/gif', 'image/webp', 'image/avif', 'image/bmp'])

export function isRasterImageType(contentType: string | null | undefined): boolean {
  if (!contentType) return false
  return RASTER.has((contentType.split(';')[0] ?? '').trim().toLowerCase())
}

/** A name safe inside `filename="..."`: no quote, separator, control character or non-ASCII. */
function safeFilename(name: string): string {
  return name.replace(/[^\w.-]+/g, '_').slice(0, 100) || 'download'
}

interface HeaderSink {
  setHeader(name: string, value: string): unknown
}

export interface ArtifactHeaderOptions {
  contentType: string
  /** The download name (already the route's own sanitized one). */
  filename?: string
  /** Used when the response is an attachment and the route has no name of its own. */
  fallbackName?: string
  /** True for a route whose bytes the app loads as <img>: a RASTER type then renders inline; any other type is still an attachment. */
  inlineRaster?: boolean
}

export function setArtifactHeaders(res: HeaderSink, { contentType, filename, fallbackName, inlineRaster = false }: ArtifactHeaderOptions): void {
  res.setHeader('Content-Type', contentType)
  res.setHeader('Content-Security-Policy', ARTIFACT_CSP)
  res.setHeader('X-Content-Type-Options', 'nosniff')
  if (inlineRaster && isRasterImageType(contentType)) return
  res.setHeader('Content-Disposition', `attachment; filename="${safeFilename(filename || fallbackName || 'download')}"`)
}
